import React from 'react';
import colors from 'config/colors';

// The transport filter of the Students list as three radio cards: every student, the students who travel by the school bus (assigned
// to a transport route), or the ones who do not. count is shown on the card that is picked, when the list is known.
const TransportRadioCards = ({ options, value, onChange, count }) => (
  <div
    role="radiogroup"
    aria-label="Transport"
    style={{ display: 'flex', gap: 10, flexWrap: 'wrap', margin: '4px 0 12px' }}>
    {options.map(option => {
      const on = option.value === value;
      return (
        <button
          key={option.value || 'all'}
          type="button"
          role="radio"
          aria-checked={on}
          onClick={() => onChange(option.value)}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 10,
            minWidth: 190,
            padding: '9px 14px',
            borderRadius: 12,
            cursor: 'pointer',
            textAlign: 'left',
            border: `1.5px solid ${on ? colors.accent : '#e3dceb'}`,
            background: on ? `${colors.accent}14` : '#fff',
            boxShadow: on ? `0 6px 16px -8px ${colors.accent}80` : 'none',
          }}>
          <span
            aria-hidden="true"
            style={{
              width: 18,
              height: 18,
              borderRadius: '50%',
              flexShrink: 0,
              boxSizing: 'border-box',
              border: `2px solid ${on ? colors.accent : '#b9aec5'}`,
              background: on ? `radial-gradient(circle, ${colors.accent} 0 40%, #fff 45%)` : '#fff',
            }}
          />
          <span style={{ flex: 1, fontSize: 13, fontWeight: 700, color: on ? colors.accentDark : '#3a3347' }}>
            {option.label}
          </span>
          {on && option.value && typeof count === 'number' && (
            <span
              style={{
                fontSize: 12,
                fontWeight: 800,
                padding: '1px 9px',
                borderRadius: 99,
                background: colors.accent,
                color: '#fff',
              }}>
              {count}
            </span>
          )}
        </button>
      );
    })}
  </div>
);

export default TransportRadioCards;
