// The Students list can be narrowed to the students who travel by the school bus (they are assigned to a transport route) or to those who
// do not. The BE answers that for the whole batch (get-school-transport-student-by-batch / get-school-non-transport-student-by-batch);
// the class and the search box then narrow that list here, and it is shown ten at a time.

export const TRANSPORT_FILTER_OPTIONS = [
  { value: 'transport', label: 'Bus travellers' },
  { value: 'nonTransport', label: 'Non-bus travellers' },
];

export const TRANSPORT_PAGE_SIZE = 10;

// classIdOf: studentId -> courseId of the class the student is in. A class that is picked keeps only its students.
export const narrowTransportList = (list, { courseId, classIdOf = {}, search = '' }) => {
  const needle = String(search || '')
    .trim()
    .toLowerCase();
  return (list || []).filter(student => {
    if (courseId && classIdOf[student.studentId] !== courseId) {
      return false;
    }
    if (!needle) {
      return true;
    }
    const name = [student.firstName, student.middleName, student.lastName].filter(Boolean).join(' ');
    return [name, student.registerNumber, student.email].some(text =>
      String(text || '')
        .toLowerCase()
        .includes(needle)
    );
  });
};

// One page (1 based) in the shape the table's pager reads: the rows and { number (0 based), size, totalElements, totalPages }.
export const pageOfList = (rows, page = 1, size = TRANSPORT_PAGE_SIZE) => {
  const totalPages = Math.ceil(rows.length / size);
  const number = Math.min(Math.max(page, 1), Math.max(totalPages, 1)) - 1;
  const content = rows.slice(number * size, number * size + size);
  return { content, number, size, numberOfElements: content.length, totalElements: rows.length, totalPages };
};
